--
-- Table structure for table `tb_approval_history`
--

DROP TABLE IF EXISTS `tb_approval_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_approval_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `approval_id` bigint NOT NULL COMMENT '审批管理表ID',
  `case_id` bigint NOT NULL COMMENT '案件ID',
  `approver_id` bigint NOT NULL COMMENT '审核人ID',
  `approval_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '审核类型: CASE_SUBMIT-案件提交, CASE_CLOSE-案件结案, FEE_APPLY-费用申请, EVIDENCE_UPLOAD-证据上传',
  `approval_title` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '审核标题',
  `approval_attachment` text COLLATE utf8mb4_bin,
  `approval_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '审核状态: PENDING-待审核, APPROVED-已通过, REJECTED-已拒绝, CANCELLED-已取消',
  `approval_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '审核意见',
  `approval_date` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '审核日期',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `update_user_id` bigint DEFAULT NULL COMMENT '修改者ID',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除: 0-否, 1-是',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-激活, INACTIVE-停用',
  PRIMARY KEY (`id`),
  KEY `idx_approval_id` (`approval_id`),
  KEY `idx_case_id` (`case_id`),
  KEY `idx_approver_id` (`approver_id`),
  KEY `idx_approval_date` (`approval_date`),
  CONSTRAINT `fk_approval_history_approval` FOREIGN KEY (`approval_id`) REFERENCES `tb_approval` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='审批历史表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tb_approval_history`
--

LOCK TABLES `tb_approval_history` WRITE;
/*!40000 ALTER TABLE `tb_approval_history` DISABLE KEYS */;
