--
-- Table structure for table `tb_audit_log`
--

DROP TABLE IF EXISTS `tb_audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_audit_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `browser` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `business_id` bigint DEFAULT NULL,
  `business_name` varchar(500) COLLATE utf8mb4_bin DEFAULT NULL,
  `business_type` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `create_time` datetime(6) DEFAULT NULL,
  `data_after` longtext COLLATE utf8mb4_bin,
  `data_before` longtext COLLATE utf8mb4_bin,
  `duration` bigint DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_bin,
  `ip_address` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `location` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `module` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `module_name` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `operation_name` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `operation_type` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `os` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `request_method` varchar(10) COLLATE utf8mb4_bin DEFAULT NULL,
  `request_params` text COLLATE utf8mb4_bin,
