  `backup_type` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `create_time` datetime(6) DEFAULT NULL,
  `database_name` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `duration` bigint DEFAULT NULL,
  `end_time` datetime(6) DEFAULT NULL,
  `error_message` varchar(2000) COLLATE utf8mb4_bin DEFAULT NULL,
