  `file_path` varchar(500) COLLATE utf8mb4_bin NOT NULL,
  `file_size` bigint DEFAULT NULL,
  `is_deleted` bit(1) DEFAULT NULL,
  `record_count` bigint DEFAULT NULL,
  `start_time` datetime(6) DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `table_count` int DEFAULT NULL,
  `update_time` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_backup_status` (`status`),
  KEY `idx_backup_type` (`backup_type`),
  KEY `idx_backup_start_time` (`start_time`),
  KEY `idx_backup_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
