DROP TABLE IF EXISTS `tb_bank_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_bank_account` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `create_time` datetime(6) NOT NULL COMMENT '创建时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建用户ID',
  `is_deleted` bit(1) DEFAULT NULL COMMENT '是否删除',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '状态',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  `update_user_id` bigint DEFAULT NULL COMMENT '更新用户ID',
  `account_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '账户名称',
  `account_number` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `account_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '账户类型',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '银行名称',
  `closing_date` date DEFAULT NULL COMMENT '销户日期',
  `currency` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '币种',
  `current_balance` decimal(18,2) DEFAULT NULL COMMENT '当前余额',
  `opening_date` date DEFAULT NULL COMMENT '开户日期',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '密码',
  `case_id` bigint DEFAULT NULL COMMENT '案件id',
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_3w6o9b9i8bk4etdwohas3yjsu` (`account_number`),
  KEY `idx_account_number` (`account_number`),
  KEY `idx_account_name` (`account_name`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_case_id` (`case_id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
