--
-- Table structure for table `tb_bankrupt_case`
--

DROP TABLE IF EXISTS `tb_bankrupt_case`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_bankrupt_case` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '案件ID',
  `case_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '案号',
  `case_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '案件名称',
  `acceptance_date` date DEFAULT NULL COMMENT '受理日期',
  `case_source` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '案件来源',
  `acceptance_court` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '受理法院',
  `designated_institution` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指定机构',
  `main_responsible_person` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主要负责人',
  `is_simplified_trial` tinyint(1) DEFAULT '0' COMMENT '是否简化审: 0-否, 1-是',
  `case_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '案由',
  `case_progress` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '案件进度: FIRST-第一阶段, SECOND-第二阶段, THIRD-第三阶段, FOURTH-第四阶段, FIFTH-第五阶段, SIXTH-第六阶段, SEVENTH-第七阶段',
  `debt_claim_deadline` datetime DEFAULT NULL COMMENT '债权申报截止时间',
  `filing_date` date DEFAULT NULL COMMENT '立案日期',
  `closing_date` date DEFAULT NULL COMMENT '结案日期',
  `bankruptcy_date` date DEFAULT NULL COMMENT '破产时间',
  `termination_date` date DEFAULT NULL COMMENT '终结时间',
  `cancellation_date` date DEFAULT NULL COMMENT '注销时间',
  `archiving_date` date DEFAULT NULL COMMENT '归档时间',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `file_upload_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件上传路径',
  `undertaking_personnel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '承办人员',
  `creator_id` bigint DEFAULT NULL COMMENT '创建人ID',
  `creator_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人姓名',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `review_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '审核状态: PENDING-待审核, APPROVED-已通过, REJECTED-已驳回',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `review_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '审核意见',
  `review_count` int DEFAULT '0' COMMENT '审核次数',
  `case_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ONGOING' COMMENT 'ONGOING-在办，AWAITING-报结，COMPLETED已结',
  `designated_judge` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指定法官',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-激活, INACTIVE-停用, DELETED-删除',
