--
-- Table structure for table `tb_case_node_alert_record`
--

DROP TABLE IF EXISTS `tb_case_node_alert_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_case_node_alert_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `node_instance_id` bigint NOT NULL COMMENT '节点实例ID, 关联tb_case_node_instance',
  `case_id` bigint NOT NULL COMMENT '案件ID, 关联tb_bankrupt_case',
  `alert_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '预警级别: SOON_DUE-即将到期, DUE_TODAY-今日到期, OVERDUE-已逾期',
  `remaining_days` int NOT NULL COMMENT '剩余天数(计算得出, 逾期时为负数)',
  `deadline_date` date NOT NULL COMMENT '截止日期',
  `alert_date` date NOT NULL COMMENT '预警触发日期',
  `is_notified` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已发送通知: 0-否, 1-是',
  `notification_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '通知类型: SYSTEM_MSG-站内消息, SMS-短信, EMAIL-邮件, MULTI-多渠道',
  `notification_time` datetime DEFAULT NULL COMMENT '通知发送时间',
  `notification_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '通知内容',
  `recipient_id` bigint DEFAULT NULL COMMENT '通知接收人ID, 关联tb_user',
  `recipient_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '通知接收人姓名',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `update_user_id` bigint DEFAULT NULL COMMENT '修改者ID',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除: 0-否, 1-是',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-激活, INACTIVE-停用',
  PRIMARY KEY (`id`),
  KEY `idx_node_instance_id` (`node_instance_id`),
  KEY `idx_case_id` (`case_id`),
