--
-- Table structure for table `tb_case_task_submission`
--

DROP TABLE IF EXISTS `tb_case_task_submission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_case_task_submission` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `case_task_id` bigint NOT NULL COMMENT '任务ID，关联tb_case_task表',
  `submission_title` varchar(500) NOT NULL COMMENT '提交标题',
  `submission_content` text COMMENT '提交内容',
  `submission_type` varchar(50) DEFAULT 'NORMAL' COMMENT '提交类型：NORMAL-普通提交，REVISION-修订提交',
  `submission_number` int DEFAULT '1' COMMENT '提交序号，同一个任务的第几次提交',
  `status` varchar(20) DEFAULT 'PENDING' COMMENT '提交状态：PENDING-待审核，APPROVED-已通过，REJECTED-已驳回',
  `reviewer_id` bigint DEFAULT NULL COMMENT '审核人ID',
  `review_opinion` text COMMENT '审核意见',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建人ID',
  `update_user_id` bigint DEFAULT NULL COMMENT '更新人ID',
  `record_status` varchar(20) DEFAULT 'ACTIVE' COMMENT '记录状态：ACTIVE-有效，DELETED-已删除',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  KEY `idx_case_task_id` (`case_task_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_status` (`status`),
  KEY `idx_record_status` (`record_status`),
  KEY `idx_create_user_id` (`create_user_id`),
  KEY `idx_case_task_id_submission_number` (`case_task_id`,`submission_number`),
  CONSTRAINT `fk_case_task_submission_task` FOREIGN KEY (`case_task_id`) REFERENCES `tb_case_task` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='案件任务提交记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tb_case_task_submission`
--

LOCK TABLES `tb_case_task_submission` WRITE;
/*!40000 ALTER TABLE `tb_case_task_submission` DISABLE KEYS */;
