--
-- Table structure for table `tb_claim_registration`
--

DROP TABLE IF EXISTS `tb_claim_registration`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_claim_registration` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '债权申报ID',
  `claim_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报编号',
  `case_id` bigint DEFAULT NULL COMMENT '案件ID',
  `case_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '案件名称',
  `debtor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '债务人',
  `creditor_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '债权人名称',
  `creditor_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '债权人类型',
  `credit_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '信用代码',
  `legal_representative` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '法定代表人',
  `service_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '送达地址',
  `agent_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人姓名',
  `agent_phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agent_id_card` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `agent_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '代理人地址',
  `account_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '账户名称',
  `creditor_bank_account` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开户银行',
  `principal` decimal(18,2) DEFAULT NULL COMMENT '申报本金',
  `interest` decimal(18,2) DEFAULT NULL COMMENT '申报利息',
  `penalty` decimal(18,2) DEFAULT NULL COMMENT '申报罚金',
  `other_losses` decimal(18,2) DEFAULT NULL COMMENT '申报其他损失',
  `total_amount` decimal(18,2) DEFAULT NULL COMMENT '申报总金额',
  `has_court_judgment` tinyint(1) DEFAULT '0' COMMENT '是否有法院判决: 0-否, 1-是',
  `has_execution` tinyint(1) DEFAULT '0' COMMENT '是否有执行: 0-否, 1-是',
  `has_collateral` tinyint(1) DEFAULT '0' COMMENT '是否有担保: 0-否, 1-是',
  `claim_nature` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '债权性质',
  `claim_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '债权类型',
  `claim_facts` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '债权事实',
  `claim_identifier` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '债权标识',
  `evidence_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '证据清单',
  `evidence_materials` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '证据材料',
  `evidence_attachments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '证据附件',
  `registration_date` datetime DEFAULT NULL COMMENT '申报日期',
  `registration_deadline` datetime DEFAULT NULL COMMENT '申报截止日期',
  `material_receiver` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料接收人',
  `material_receive_date` datetime DEFAULT NULL COMMENT '材料接收日期',
  `material_completeness` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料完整性: COMPLETE-完整, INCOMPLETE-不完整, PENDING-待补充',
  `registration_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '登记状态: PENDING-待登记, REGISTERED-已登记, REJECTED-已驳回',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-激活, INACTIVE-停用, DELETED-删除',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除: 0-否, 1-是',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `update_user_id` bigint DEFAULT NULL COMMENT '修改者ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_claim_no` (`claim_no`),
  UNIQUE KEY `UK_g5pxf5sg7irkc2l8xtb4fy4wk` (`claim_no`),
  KEY `idx_case_id` (`case_id`),
  KEY `idx_creditor_name` (`creditor_name`),
  KEY `idx_claim_type` (`claim_type`),
  KEY `idx_registration_status` (`registration_status`),
  KEY `idx_total_amount` (`total_amount`),
  KEY `idx_registration_date` (`registration_date`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`),
  CONSTRAINT `fk_claim_registration_case` FOREIGN KEY (`case_id`) REFERENCES `tb_bankrupt_case` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='债权申报登记表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tb_claim_registration`
--

