--
-- Table structure for table `tb_claim_review`
--

DROP TABLE IF EXISTS `tb_claim_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_claim_review` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `create_time` datetime(6) NOT NULL COMMENT '创建时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建用户ID',
  `is_deleted` bit(1) DEFAULT NULL COMMENT '是否删除',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '状态',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  `update_user_id` bigint DEFAULT NULL COMMENT '更新用户ID',
  `adjustment_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '调整原因',
  `case_id` bigint DEFAULT NULL COMMENT '案件ID',
  `claim_registration_id` bigint NOT NULL COMMENT '债权申报ID',
  `collateral_amount` decimal(18,2) DEFAULT NULL COMMENT '担保金额',
  `collateral_property` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保物',
  `collateral_term` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保期限',
  `collateral_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保类型',
  `collateral_validity` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '担保有效性',
  `confirmed_claim_nature` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '确认债权性质',
  `confirmed_interest` decimal(18,2) DEFAULT NULL COMMENT '确认利息',
  `confirmed_other_losses` decimal(18,2) DEFAULT NULL COMMENT '确认其他损失',
  `confirmed_penalty` decimal(18,2) DEFAULT NULL COMMENT '确认违约金',
  `confirmed_principal` decimal(18,2) DEFAULT NULL COMMENT '确认本金',
  `confirmed_total_amount` decimal(18,2) DEFAULT NULL COMMENT '确认总金额',
  `creditor_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '债权人名称',
  `declared_interest` decimal(18,2) DEFAULT NULL COMMENT '申报利息',
  `declared_other_losses` decimal(18,2) DEFAULT NULL COMMENT '申报其他损失',
  `declared_penalty` decimal(18,2) DEFAULT NULL COMMENT '申报违约金',
  `declared_principal` decimal(18,2) DEFAULT NULL COMMENT '申报本金',
  `declared_total_amount` decimal(18,2) DEFAULT NULL COMMENT '申报总金额',
  `evidence_authenticity` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证据真实性',
  `evidence_legality` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证据合法性',
  `evidence_relevance` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '证据关联性',
  `evidence_review_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '证据审查备注',
  `expired_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '逾期原因',
  `insufficient_evidence_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '证据不足原因',
  `is_conditional` bit(1) DEFAULT NULL COMMENT '是否附条件',
  `is_joint_liability` bit(1) DEFAULT NULL COMMENT '是否连带责任',
  `is_term` bit(1) DEFAULT NULL COMMENT '是否定期',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '备注',
  `review_attachments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '审查附件',
  `review_basis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '审查依据',
  `review_conclusion` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '审查结论',
  `review_date` datetime(6) DEFAULT NULL COMMENT '审查日期',
  `review_report` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '审查报告',
  `review_round` int DEFAULT NULL COMMENT '审查轮次',
  `review_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '审查状态',
  `review_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '审查摘要',
  `reviewer` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '审查人',
  `unconfirmed_interest` decimal(18,2) DEFAULT NULL COMMENT '未确认利息',
  `unconfirmed_other_losses` decimal(18,2) DEFAULT NULL COMMENT '未确认其他损失',
  `unconfirmed_penalty` decimal(18,2) DEFAULT NULL COMMENT '未确认违约金',
  `unconfirmed_principal` decimal(18,2) DEFAULT NULL COMMENT '未确认本金',
  `unconfirmed_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '未确认原因',
  `unconfirmed_total_amount` decimal(18,2) DEFAULT NULL COMMENT '未确认总金额',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

