DROP TABLE IF EXISTS `tb_dictionary_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_dictionary_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category_id` bigint NOT NULL,
  `create_time` datetime(6) DEFAULT NULL,
  `create_user_id` bigint DEFAULT NULL,
  `description` varchar(500) COLLATE utf8mb4_bin DEFAULT NULL,
  `is_deleted` bit(1) DEFAULT NULL,
  `item_code` varchar(100) COLLATE utf8mb4_bin NOT NULL,
  `item_name` varchar(100) COLLATE utf8mb4_bin NOT NULL,
  `item_value` varchar(200) COLLATE utf8mb4_bin DEFAULT NULL,
  `sort_order` int DEFAULT NULL,
  `status` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `update_time` datetime(6) DEFAULT NULL,
  `update_user_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_item_category_id` (`category_id`),
  KEY `idx_item_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=131 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
