--
-- Table structure for table `tb_document_delivery`
--

DROP TABLE IF EXISTS `tb_document_delivery`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_document_delivery` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `case_id` bigint DEFAULT NULL COMMENT '案件ID',
  `case_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '案号',
  `case_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '案件名称',
  `document_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '文书名称',
  `document_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '文书类型: COURT_NOTICE-法院通知, JUDGMENT-判决书, VERDICT-裁定书, NOTICE-通知书, OTHER-其他',
  `recipient_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '受送达人',
  `recipient_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '受送达人类型: DEBTOR-债务人, CREDITOR-债权人, LAWYER-律师, COURT-法院, OTHER-其他',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '联系电话',
  `delivery_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '送达地址',
  `delivery_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '送达方式: POST-邮寄, EMAIL-邮件, EXPRESS-快递, IN_PERSON-当面送达, ELECTRONIC-电子送达, OTHER-其他',
  `send_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '发送状态: PENDING-待发送, SENT-已发送,FAILED-发送失败, REJECTED-被拒收，SENDING-发送中',
  `delivery_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '送达内容（富文本）',
  `document_attachment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '文书附件路径',
  `send_time` datetime DEFAULT NULL COMMENT '发送时间',
  `delivery_time` datetime DEFAULT NULL COMMENT '送达时间',
  `failure_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '失败原因',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `update_user_id` bigint DEFAULT NULL COMMENT '修改者ID',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除: 0-否, 1-是',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT 'PENDING' COMMENT '状态: PENDING-待审批，APPROVED-已通过，REJECTED-已驳回''',
  `remark` text COLLATE utf8mb4_bin COMMENT '审批意见',
  `abbreviation` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `document_number` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `approval_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_case_id` (`case_id`),
  KEY `idx_case_number` (`case_number`),
  KEY `idx_send_status` (`send_status`),
  KEY `idx_document_type` (`document_type`),
  KEY `idx_recipient_type` (`recipient_type`),
  KEY `idx_delivery_method` (`delivery_method`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_status` (`status`),
  CONSTRAINT `fk_document_delivery_case` FOREIGN KEY (`case_id`) REFERENCES `tb_bankrupt_case` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='文书送达表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tb_document_delivery`
--

LOCK TABLES `tb_document_delivery` WRITE;
/*!40000 ALTER TABLE `tb_document_delivery` DISABLE KEYS */;
INSERT INTO `tb_document_delivery` VALUES (1,1,'2026-破字第001号','北京某科技有限公司破产清算案','破产受理通知书','COURT_NOTICE','北京某科技有限公司','DEBTOR','13800138001','北京市朝阳区建国路88号','POST','SENT','<p>根据《中华人民共和国企业破产法》规定，本院已受理北京某科技有限公司的破产清算申请。</p><p>请贵公司自收到本通知书之日起15日内，向本院提交财产状况说明、债务清册、债权清册等材料。</p>','/uploads/documents/2026/01/notice_001.pdf','2026-01-10 09:00:00','2026-01-12 14:30:00',NULL,'2026-01-17 09:58:26','2026-01-17 14:25:58',1,NULL,0,'PENDING',NULL,NULL,NULL,NULL),(2,1,'2026-破字第001号','北京某科技有限公司破产清算案','债权申报通知书','NOTICE','刘备','CREDITOR','13800001001','北京市海淀区中关村大街1号','EXPRESS','SENT','<p>尊敬的债权人：</p><p>北京某科技有限公司破产清算案已由本院受理，请您于2026年2月15日前向管理人申报债权。</p><p>申报地址：北京市朝阳区建国路88号</p><p>联系人：王工作人员</p><p>联系电话：13800138003</p>','/uploads/documents/2026/01/creditor_notice_001.pdf','2026-01-10 10:00:00','2026-01-13 10:20:00',NULL,'2026-01-17 09:58:26','2026-01-17 14:26:00',1,NULL,0,'PENDING',NULL,NULL,NULL,NULL),(3,1,'2026-破字第001号','北京某科技有限公司破产清算案','第一次债权人会议通知书','COURT_NOTICE','关羽','CREDITOR','13800001002','北京市东城区王府井大街100号','EXPRESS','SENT','<p>尊敬的债权人：</p><p>北京某科技有限公司第一次债权人会议定于2026年2月20日上午9:00在本院第一审判庭召开。</p><p>请准时参加。</p>','/uploads/documents/2026/01/meeting_notice_001.pdf','2026-01-15 14:00:00',NULL,NULL,'2026-01-17 09:58:26','2026-01-17 14:26:03',1,NULL,0,'PENDING',NULL,NULL,NULL,NULL),(4,2,'2026-破字第002号','郜艳破产清算案','破产受理裁定书','VERDICT','郜艳','DEBTOR','18656953556','上海市浦东新区陆家嘴环路1000号','IN_PERSON','SENT','<p>根据《中华人民共和国企业破产法》第二条之规定，本院裁定受理郜艳的破产清算申请。</p><p>本裁定自送达之日起生效。</p>','/uploads/documents/2026/01/verdict_002.pdf','2026-01-08 11:00:00','2026-01-08 11:30:00',NULL,'2026-01-17 09:58:26','2026-01-17 14:26:05',1,NULL,0,'PENDING',NULL,NULL,NULL,NULL),(5,2,'2026-破字第002号','郜艳破产清算案','财产申报通知书','NOTICE','郜艳','DEBTOR','18656953556','上海市浦东新区陆家嘴环路1000号','EMAIL','SENT','<p>请于收到本通知书之日起10日内，向管理人提交以下材料：</p><p>1. 财产状况说明</p><p>2. 债务清册</p><p>3. 债权清册</p><p>4. 有关财务会计报告</p>','/uploads/documents/2026/01/property_notice_002.pdf','2026-01-09 09:30:00',NULL,NULL,'2026-01-17 09:58:26','2026-01-17 14:26:06',1,NULL,0,'APPROVED',NULL,NULL,NULL,NULL),(6,3,'2026-破字第003号','广州某制造企业破产和解案','破产和解申请书','OTHER','广州某制造企业','DEBTOR','13900139001','广州市天河区天河路385号','ELECTRONIC','SENT','<p>根据《中华人民共和国企业破产法》第九十五条之规定，债务人可以直接向人民法院申请和解。</p><p>本院已受理贵公司的破产和解申请。</p>','/uploads/documents/2026/01/reconciliation_003.pdf','2026-01-05 16:00:00','2026-01-06 09:15:00',NULL,'2026-01-17 09:58:26','2026-01-17 14:26:09',1,NULL,0,'APPROVED',NULL,NULL,NULL,NULL),(8,5,'（2024）沪02破1号','上海某实业公司破产重整案','管理人指定通知书','COURT_NOTICE','江哥','OTHER','15199999999','北京市朝阳区建国路88号','POST','SENT','<p>根据《中华人民共和国企业破产法》第二十四条之规定，本院指定江哥为本案管理人。</p><p>请自收到本通知书之日起，配合管理人开展各项工作。</p>','/uploads/documents/2026/01/administrator_notice_005.pdf',NULL,NULL,NULL,'2026-01-17 09:58:26','2026-01-17 14:26:11',16,NULL,0,'APPROVED',NULL,NULL,NULL,NULL),(9,5,'（2024）沪02破1号','上海某实业公司破产重整案','破产清算公告','OTHER','全体债权人','CREDITOR',NULL,NULL,'ELECTRONIC','SENT','<p>北京某科技有限公司破产清算案公告</p><p>本院于2本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受理北京某科技有限公司的破产清算申请。</p><p>债权人应于2026年3月15日前向管理人申报债权本院于2026年1月15日裁定受