DROP TABLE IF EXISTS `tb_document_edit_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_document_edit_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `file_id` bigint NOT NULL COMMENT '文件 ID',
  `version` int NOT NULL COMMENT '版本号',
  `editor_id` bigint NOT NULL COMMENT '编辑人 ID',
  `editor_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编辑人名称',
  `edit_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '编辑时间',
  `edit_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'MODIFY' COMMENT '编辑类型：CREATE, MODIFY, SAVE',
  `changes` text COLLATE utf8mb4_unicode_ci COMMENT '变更内容（JSON 格式）',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件路径',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_file_id` (`file_id`),
  KEY `idx_version` (`version`),
  KEY `idx_editor_id` (`editor_id`),
  KEY `idx_edit_time` (`edit_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文档编辑历史表';
/*!40101 SET character_set_client = @saved_cs_client */;

