CREATE TABLE `tb_document_template_field` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `template_id` bigint NOT NULL COMMENT '模板 ID',
  `field_label` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段标签（显示名称）',
  `field_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段名称（占位符名称）',
  `field_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'TEXT' COMMENT '字段类型：TEXT, NUMBER, DATE, TABLE, IMAGE',
  `is_required` tinyint(1) DEFAULT '0' COMMENT '是否必填：0-否，1-是',
  `sort_order` int DEFAULT '0' COMMENT '排序顺序',
  `default_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '默认值',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段描述',
