--
-- Table structure for table `tb_file_lock`
--

DROP TABLE IF EXISTS `tb_file_lock`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_file_lock` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键 ID',
  `file_id` bigint NOT NULL COMMENT '文件 ID',
  `user_id` bigint NOT NULL COMMENT '锁定用户 ID',
  `user_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名称',
  `lock_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '锁定时间',
  `expire_time` datetime DEFAULT NULL COMMENT '过期时间',
  `lock_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'EDIT' COMMENT '锁定类型：EDIT, PREVIEW',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'LOCKED' COMMENT '状态：LOCKED, UNLOCKED, EXPIRED',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_file_id` (`file_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_lock_time` (`lock_time`),
  KEY `idx_expire_time` (`expire_time`),
