  `create_time` datetime(6) NOT NULL,
  `create_user_id` bigint DEFAULT NULL,
  `is_deleted` bit(1) DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `update_time` datetime(6) DEFAULT NULL,
  `update_user_id` bigint DEFAULT NULL,
  `biz_id` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `biz_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `delete_time` datetime(6) DEFAULT NULL,
  `delete_user_id` bigint DEFAULT NULL,
  `file_extension` varchar(50) COLLATE utf8mb4_bin DEFAULT NULL,
  `file_hash` varchar(64) COLLATE utf8mb4_bin DEFAULT NULL,
  `file_path` varchar(500) COLLATE utf8mb4_bin NOT NULL,
  `file_size` bigint DEFAULT NULL,
  `file_status` int DEFAULT NULL,
  `mime_type` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  `original_file_name` varchar(255) COLLATE utf8mb4_bin NOT NULL,
  `stored_file_name` varchar(255) COLLATE utf8mb4_bin NOT NULL,
  `upload_time` datetime(6) DEFAULT NULL,
  `upload_user_id` bigint DEFAULT NULL,
  `description` text COLLATE utf8mb4_bin,
  `sort_order` int DEFAULT NULL,
  `thumbnail_path` varchar(500) COLLATE utf8mb4_bin DEFAULT NULL,
  `video_duration` bigint DEFAULT NULL,
  `video_height` int DEFAULT NULL,
  `video_status` varchar(20) COLLATE utf8mb4_bin DEFAULT NULL,
  `video_width` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_biz_type` (`biz_type`),
  KEY `idx_biz_id` (`biz_id`),
  KEY `idx_file_status` (`file_status`),
  KEY `idx_status` (`status`),
  KEY `idx_upload_time` (`upload_time`),
  KEY `idx_upload_user_id` (`upload_user_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_biz_type_biz_id` (`biz_type`,`biz_id`),
  KEY `idx_sort_order` (`sort_order`),
  KEY `idx_biz_type_biz_ids` (`biz_type`,`biz_id`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=555 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
