--
-- Table structure for table `tb_fund_account`
--

DROP TABLE IF EXISTS `tb_fund_account`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_fund_account` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `create_time` datetime(6) NOT NULL COMMENT '创建时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建用户ID',
  `is_deleted` bit(1) DEFAULT NULL COMMENT '是否删除',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '状态',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  `update_user_id` bigint DEFAULT NULL COMMENT '更新用户ID',
  `account_balance_limit` decimal(18,2) DEFAULT NULL COMMENT '账户余额限额',
  `account_id` bigint DEFAULT NULL COMMENT '账户ID',
  `account_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '账户名称',
  `account_permission` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '账户权限',
  `account_purpose` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '账户用途',
  `account_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '账户类型',
  `bank_account` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL,
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '银行名称',
  `case_id` bigint DEFAULT NULL COMMENT '案件ID',
  `case_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '案件名称',
  `closing_date` datetime(6) DEFAULT NULL COMMENT '销户日期',
  `current_balance` decimal(18,2) DEFAULT NULL COMMENT '当前余额',
  `freeze_date` datetime(6) DEFAULT NULL COMMENT '冻结日期',
  `freeze_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '冻结原因',
  `initial_balance` decimal(18,2) DEFAULT NULL COMMENT '初始余额',
  `is_frozen` bit(1) DEFAULT NULL COMMENT '是否冻结',
  `opening_date` datetime(6) DEFAULT NULL COMMENT '开户日期',
  `unfreeze_date` datetime(6) DEFAULT NULL COMMENT '解冻日期',
  PRIMARY KEY (`id`),
  KEY `idx_case_id` (`case_id`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tb_fund_account`
--

