CREATE TABLE `tb_fund_flow` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `create_time` datetime(6) NOT NULL COMMENT '创建时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建用户ID',
  `is_deleted` bit(1) DEFAULT NULL COMMENT '是否删除',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '状态',
  `update_time` datetime(6) DEFAULT NULL COMMENT '更新时间',
  `update_user_id` bigint DEFAULT NULL COMMENT '更新用户ID',
  `account_id` bigint DEFAULT NULL COMMENT '账户ID',
  `amount` decimal(18,2) DEFAULT NULL COMMENT '金额',
  `attachments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '附件',
  `balance_after` decimal(18,2) DEFAULT NULL COMMENT '交易后余额',
  `balance_before` decimal(18,2) DEFAULT NULL COMMENT '交易前余额',
  `case_id` bigint DEFAULT NULL COMMENT '案件ID',
  `case_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '案件名称',
  `check_date` datetime(6) DEFAULT NULL COMMENT '审核日期',
  `check_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '审核状态',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '描述',
  `expense_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '费用类型',
  `flow_category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '流水类别',
  `flow_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '流水类型',
  `fund_account_id` bigint DEFAULT NULL COMMENT '资金账户ID',
  `is_reversed` bit(1) DEFAULT NULL COMMENT '是否冲正',
  `operation_time` datetime(6) DEFAULT NULL COMMENT '操作时间',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `related_business_id` bigint DEFAULT NULL COMMENT '关联业务ID',
  `related_business_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '关联业务类型',
  `related_document` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '关联单据',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '备注',
  `reversal_date` datetime(6) DEFAULT NULL COMMENT '冲正日期',
  `reversal_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '冲正原因',
  `reversed_flow_id` bigint DEFAULT NULL COMMENT '被冲正流水ID',
  `transaction_date` datetime(6) DEFAULT NULL COMMENT '交易日期',
