DROP TABLE IF EXISTS `tb_lib_document`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_lib_document` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `document_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '文档名称',
  `document_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '文档编码(唯一标识)',
  `folder_id` bigint DEFAULT NULL COMMENT '所属文件夹ID, NULL表示根目录',
  `document_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '文档类型: WORD-Word文档, EXCEL-Excel表格, PDF-PDF文档, OTHER-其他',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '原始文件名',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '文件存储路径',
  `file_size` bigint DEFAULT '0' COMMENT '文件大小(字节)',
  `file_extension` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '文件扩展名(如: docx, xlsx, pdf)',
  `mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'MIME类型',
  `current_version` int DEFAULT '1' COMMENT '当前版本号',
  `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '文档描述',
  `tags` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '标签(逗号分隔)',
  `is_public` tinyint(1) DEFAULT '0' COMMENT '是否公开: 0-否, 1-是',
  `is_locked` tinyint(1) DEFAULT '0' COMMENT '是否锁定: 0-否, 1-是(锁定时不可编辑)',
  `locked_by` bigint DEFAULT NULL COMMENT '锁定者ID',
  `locked_time` datetime DEFAULT NULL COMMENT '锁定时间',
  `download_count` int DEFAULT '0' COMMENT '下载次数',
  `view_count` int DEFAULT '0' COMMENT '浏览次数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `update_user_id` bigint DEFAULT NULL COMMENT '修改者ID',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除: 0-否, 1-是',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-激活, INACTIVE-停用, DELETED-删除, DRAFT-草稿',
  `create_user_name` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_document_code` (`document_code`),
  UNIQUE KEY `uk_lib_doc_code` (`document_code`),
  KEY `idx_folder_id` (`folder_id`),
  KEY `idx_document_type` (`document_type`),
  KEY `idx_create_user_id` (`create_user_id`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_folder_status` (`folder_id`,`status`),
  KEY `idx_is_public` (`is_public`),
  KEY `idx_lib_doc_folder_id` (`folder_id`),
  KEY `idx_lib_doc_type` (`document_type`),
  KEY `idx_lib_doc_status` (`status`),
  KEY `idx_lib_doc_create_user_id` (`create_user_id`),
  KEY `idx_lib_doc_create_time` (`create_time`),
  CONSTRAINT `fk_lib_document_folder` FOREIGN KEY (`folder_id`) REFERENCES `tb_lib_document_folder` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='文档表';
