  `sort_order` int DEFAULT '0' COMMENT '排序序号',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '文件夹描述',
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '文件夹图标',
  `color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '文件夹颜色',
  `is_public` tinyint(1) DEFAULT '0' COMMENT '是否公开: 0-否, 1-是',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `update_user_id` bigint DEFAULT NULL COMMENT '修改者ID',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除: 0-否, 1-是',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-激活, INACTIVE-停用, DELETED-删除',
  `create_user_name` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_folder_path` (`folder_path`),
  UNIQUE KEY `uk_lib_folder_path` (`folder_path`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_create_user_id` (`create_user_id`),
  KEY `idx_status` (`status`),
  KEY `idx_parent_status` (`parent_id`,`status`),
  KEY `idx_lib_folder_parent_id` (`parent_id`),
  KEY `idx_lib_folder_status` (`status`),
  KEY `idx_lib_folder_create_user_id` (`create_user_id`),
  CONSTRAINT `fk_lib_folder_parent` FOREIGN KEY (`parent_id`) REFERENCES `tb_lib_document_folder` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='文档文件夹表';
