  `new_value` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '变更后值',
  `ip_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '操作IP地址',
  `user_agent` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '用户代理',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `create_user_id` bigint DEFAULT NULL COMMENT '操作者ID',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '是否删除: 0-否, 1-是',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT 'ACTIVE' COMMENT '状态: ACTIVE-激活, DELETED-删除',
  `update_time` datetime(6) DEFAULT NULL,
  `update_user_id` bigint DEFAULT NULL,
  `create_user_name` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_document_id` (`document_id`),
  KEY `idx_folder_id` (`folder_id`),
  KEY `idx_operation_type` (`operation_type`),
  KEY `idx_create_user_id` (`create_user_id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_status` (`status`),
  KEY `idx_lib_log_doc_id` (`document_id`),
  KEY `idx_lib_log_folder_id` (`folder_id`),
  KEY `idx_lib_log_op_type` (`operation_type`),
  KEY `idx_lib_log_create_user_id` (`create_user_id`),
  KEY `idx_lib_log_create_time` (`create_time`),
  CONSTRAINT `fk_lib_log_document` FOREIGN KEY (`document_id`) REFERENCES `tb_lib_document` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_lib_log_folder` FOREIGN KEY (`folder_id`) REFERENCES `tb_lib_document_folder` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=163 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='文档操作日志表';
