CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cleanup_expired_locks`()
BEGIN
  UPDATE tb_file_lock
  SET status = 'EXPIRED'
  WHERE status = 'LOCKED'
  AND (expire_time IS NULL OR expire_time < NOW());
  
  SELECT ROW_COUNT() AS affected_rows;
END ;;
